export function loopsum(n: number): number {
  let s = 0;
  for (let i = 0; i < n; i++) {
    s = (s + i + i) % 1000000007;
  }
  return s;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { loopsum } from "./loopsum.js";

test("loopsum", () => {
  assert.equal(loopsum(0), 0);
  assert.equal(loopsum(10), 285);
  assert.equal(loopsum(1000), 332833500);
});
